const KEY='volleyworld-v1';let state;try{state=JSON.parse(localStorage.getItem(KEY));if(!state||state.version!==1)state=V.fresh()}catch{state=V.fresh()}let tab='table',round=Math.max(0,state.rounds.findIndex(r=>r.some(m=>!m.sets))),search='',editId=null;
const $=id=>document.getElementById(id), names={CEV:'Châu Âu',NORCECA:'Bắc, Trung Mỹ & Caribe',AVC:'Châu Á & Đại Dương',CSV:'Nam Mỹ',CAVB:'Châu Phi'};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('saved').textContent='● Đã lưu trên trình duyệt'}catch{$('saved').textContent='Không thể lưu · hãy xuất tiến độ'}}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2600)}
function team(id){let t=V.get(id);return `<span class="team"><span class="flag">${t.flag}</span>${t.name}</span>`}
function allMatches(){return [...state.rounds.flat(),...(state.playin||[]),...Object.values(state.bracket||{}).filter(Array.isArray).flat()]}
function findMatch(id){return allMatches().find(m=>m.id===id)}
function navigate(t){tab=t;render()}
function render(){let done=state.rounds.flat().filter(m=>m.sets).length,rd=state.rounds.filter(r=>r.every(m=>m.sets)).length,stage=state.bracket?'Playoff':state.playin?'Vé vớt':'League phase';$('stats').innerHTML=[['32','ĐỘI TUYỂN · 5 KHU VỰC'],[`${rd}<small style="font-size:15px;color:#859287"> / 31</small>`,'VÒNG LEAGUE HOÀN TẤT'],[done,'TRẬN LEAGUE ĐÃ ĐẤU'],[stage,'GIAI ĐOẠN HIỆN TẠI']].map(([n,l])=>`<div class="stat"><b>${n}</b><span>${l}</span></div>`).join('');$('nav').innerHTML=[['table','Bảng xếp hạng'],['league','Lịch thi đấu'],['playoff','Vé vớt & Playoff'],['teams','32 đội tuyển'],['rules','Thể thức']].map(([id,n])=>`<button class="${tab===id?'active':''}" onclick="navigate('${id}')">${n}</button>`).join('');$('heroAction').textContent=state.bracket?'Đến vòng playoff →':state.playin?'Đến vòng vé vớt →':'Tiếp tục giải đấu →';$('heroAction').onclick=()=>navigate(state.playin?'playoff':'league');if(tab==='table')renderTable();if(tab==='league')renderLeague();if(tab==='playoff')renderPlayoff();if(tab==='teams')renderTeams();if(tab==='rules')renderRules();}
function renderTable(){let rows=V.standings(state);$('content').innerHTML=`<div class="section-head"><div><h2>League standings</h2><p class="sub">Thắng / thua → hiệu số set → hiệu số điểm → đối đầu → bốc thăm</p></div><div class="controls"><input class="search" placeholder="Tìm đội tuyển…" aria-label="Tìm đội tuyển" id="search"><button class="primary" onclick="navigate('league')">Thi đấu vòng tiếp theo →</button></div></div><div class="legend"><span><i class="dot"></i>1–12: Vào thẳng playoff</span><span><i class="dot yellow"></i>13–20: Vòng vé vớt</span><span><i class="dot gray"></i>21–32: Bị loại sau league</span></div><div class="panel table-wrap"><table><thead><tr><th>#</th><th>ĐỘI TUYỂN</th><th>KHU VỰC</th><th>TRẬN</th><th>W</th><th>L</th><th>SET +/−</th><th>HS SET</th><th>ĐIỂM +/−</th><th>HS ĐIỂM</th></tr></thead><tbody id="rows"></tbody></table></div>`;const draw=()=>{$('rows').innerHTML=rows.map((t,i)=>({...t,pos:i+1})).filter(t=>t.name.toLowerCase().includes(search.toLowerCase())||t.id.toLowerCase().includes(search.toLowerCase())).map(t=>`<tr class="${t.pos<=12?'direct':t.pos<=20?'in':'out'}"><td>${t.pos}</td><td>${team(t.id)}</td><td><span class="badge">${t.region}</span></td><td>${t.w+t.l}</td><td><b>${t.w}</b></td><td>${t.l}</td><td>${t.sf} : ${t.sa}</td><td><b>${signed(t.sf-t.sa)}</b></td><td>${t.pf} : ${t.pa}</td><td>${signed(t.pf-t.pa)}</td></tr>`).join('')};$('search').value=search;$('search').oninput=e=>{search=e.target.value;draw()};draw();}
function signed(n){return n>0?'+'+n:n}
function isLocked(m){if(m.id.startsWith('L'))return !!state.playin;if(m.id.startsWith('P'))return !!state.bracket;let b=state.bracket;if(!b)return false;const next={R:'qf',Q:'sf',S:'final'};return !!b[next[m.id[0]]]?.length}
function card(m,label='',locked=false){locked=isLocked(m);let[a,b]=V.score(m),win=V.winner(m),seed=state.bracket?.seeds;return `<article class="match"><div class="match-top"><span>${label||'BEST OF FIVE'}</span><span>${m.sets?'HOÀN TẤT':'CHƯA ĐẤU'}</span></div>${[m.a,m.b].map((id,i)=>`<div class="side ${win===id?'win':''}">${team(id)}${seed&&seed[id]?`<span class="badge">S${seed[id]}</span>`:''}<span class="result">${m.sets?(i===0?a:b):'–'}</span></div>`).join('')}${m.sets?`<div class="sets">${m.sets.map((s,i)=>`S${i+1} ${s[0]}–${s[1]}`).join(' · ')}</div>`:''}<div class="match-actions">${!m.sets?`<button class="primary" onclick="simOne('${m.id}')">Mô phỏng</button>`:''}<button ${locked?'disabled':''} onclick="editMatch('${m.id}')">${m.sets?'Xem / sửa điểm':'Nhập điểm'}</button></div></article>`}
function renderLeague(){$('content').innerHTML=`<div class="section-head"><div><h2>Lịch thi đấu league</h2><p class="sub">Vòng tròn một lượt · 16 trận / vòng · tổng 496 trận</p></div><div class="controls"><select aria-label="Chọn vòng" onchange="round=Number(this.value);renderLeague()">${state.rounds.map((r,i)=>`<option value="${i}" ${i===round?'selected':''}>Vòng ${i+1}${r.every(m=>m.sets)?' ✓':''}</option>`).join('')}</select><button onclick="simRound()" ${state.rounds[round].every(m=>m.sets)?'disabled':''}>Chạy vòng ${round+1}</button><button class="primary" onclick="simLeague()" ${V.leagueDone(state)?'disabled':''}>Chạy hết league</button></div></div><div class="progress"><i style="width:${state.rounds.flat().filter(m=>m.sets).length/496*100}%"></i></div><div style="height:20px"></div>${V.leagueDone(state)?`<div class="notice"><b>League đã kết thúc!</b> Top 12 đi tiếp; hạng 13–20 tranh 4 vé còn lại. <button onclick="navigate('playoff')">Đến vòng vé vớt →</button></div>`:''}<div class="grid">${state.rounds[round].map(m=>card(m,`VÒNG ${round+1}`,!!state.playin)).join('')}</div><div class="section-head" style="margin-top:20px"><button ${round===0?'disabled':''} onclick="round--;renderLeague()">← Vòng trước</button><button ${round===30?'disabled':''} onclick="round++;renderLeague()">Vòng sau →</button></div>`;}
function simOne(id){let m=findMatch(id);if(!m||m.sets)return;V.simulate(m);V.advance(state);save();render()}
function simRound(){state.rounds[round].filter(m=>!m.sets).forEach(V.simulate);save();render();toast(`Đã hoàn tất vòng ${round+1}`)}
function simLeague(){if(!confirm('Mô phỏng tất cả trận league chưa đấu? Kết quả đã có được giữ nguyên.'))return;state.rounds.flat().filter(m=>!m.sets).forEach(V.simulate);save();render();toast('League đã hoàn tất. Vòng vé vớt đã sẵn sàng!')}
function startPlayin(){V.startPlayin(state);save();render()}
function drawBracket(){V.draw(state);save();render();toast('Đã bốc thăm 4 nhánh. Nhánh đấu được giữ cố định!')}
function simStage(key){state.bracket[key].filter(m=>!m.sets).forEach(V.simulate);V.advance(state);save();render()}
function renderPlayoff(){if(!V.leagueDone(state)){$('content').innerHTML=`<div class="notice"><span class="badge">CHẶNG TIẾP THEO</span><h2 style="margin-top:12px">Con đường đến chức vô địch</h2><p>Hoàn tất 31 vòng league để xác định 12 đội vào thẳng playoff và 8 đội tranh vé vớt.</p><button class="primary" onclick="navigate('league')">Tiếp tục league →</button></div><div class="rule-grid"><div class="panel rule"><h3>01 / Vòng vé vớt</h3><p>Hạng 13–20 · 13 vs 20, 14 vs 19, 15 vs 18, 16 vs 17. Bốn trận BO5, bốn vé đi tiếp.</p></div><div class="panel rule"><h3>02 / Playoff 16 đội</h3><p>Bốn nhánh, mỗi nhánh đủ seed 1–4. Bốc thăm một lần, sau đó đi theo nhánh đến chung kết.</p></div></div>`;return}if(!state.playin){$('content').innerHTML=`<div class="notice"><h2>Đã xác định top 20</h2><p>12 đội đầu vào thẳng playoff. Tạo các cặp vé vớt theo thứ hạng league.</p><button class="primary" onclick="startPlayin()">Tạo vòng vé vớt →</button></div>`;return}const pDone=state.playin.every(m=>m.sets),b=state.bracket;let html=`<div class="section-head"><div><h2>Vòng vé vớt</h2><p class="sub">Hạng 13–20 · một trận BO5 loại trực tiếp</p></div>${!pDone?`<button class="primary" onclick="state.playin.filter(m=>!m.sets).forEach(V.simulate);save();render()">Chạy vòng vé vớt</button>`:!b?`<button class="primary" onclick="drawBracket()">Bốc thăm playoff →</button>`:'<span class="badge">ĐÃ HOÀN TẤT</span>'}</div><div class="grid">${state.playin.map((m,i)=>card(m,`HẠNG ${13+i} vs ${20-i}`,!!b)).join('')}</div>`;if(b){let champion=b.final[0]&&V.winner(b.final[0]);if(champion)html+=`<div class="podium" style="margin-top:25px"><div class="trophy">🏆</div><div class="eyebrow" style="color:#d6f46a">WORLD CHAMPION</div><h2>${team(champion)}</h2><p>Á quân: ${V.get(V.loser(b.final[0])).name}${b.bronze[0]?.sets?' · Hạng ba: '+V.get(V.winner(b.bronze[0])).name:' · Trận tranh hạng ba chưa hoàn tất'}</p></div>`;html+=`<div class="section-head" style="margin-top:32px"><div><h2>Đường đến ngôi vô địch</h2><p class="sub">Bốc thăm một lần · nhánh A–B gặp nhau ở bán kết 1, C–D ở bán kết 2</p></div></div><div class="bracket-scroll"><div class="bracket">`;for(const [key,title,cls]of [['r16','Vòng 16 đội',''],['qf','Tứ kết','qf'],['sf','Bán kết','sf'],['final','Chung kết','fin']]){html+=`<div class="bracket-col ${cls}"><div class="section-head"><h3>${title}</h3>${b[key].length&&b[key].some(m=>!m.sets)?`<button onclick="simStage('${key}')" style="padding:5px 8px;font-size:10px">Chạy vòng</button>`:''}</div>`;if(!b[key].length)html+=`<div class="placeholder">Chờ kết quả vòng trước</div>`;else for(let i=0;i<b[key].length;i++){if(key==='r16'&&i%2===0)html+=`<div class="branch-label">NHÁNH ${'ABCD'[i/2]}</div>`;html+=card(b[key][i],key==='r16'?`NHÁNH ${'ABCD'[Math.floor(i/2)]}`:title,Object.values(b).filter(Array.isArray).flat().some(m=>m.sets&&(m.a===V.winner(b[key][i])||m.b===V.winner(b[key][i]))&&m.id!==b[key][i].id&&m.id[0]!==b[key][i].id[0]));}if(key==='final'){html+=`<h3 class="bronze">Tranh hạng ba</h3>`;html+=b.bronze.length?card(b.bronze[0],'TRANH HẠNG BA'): '<div class="placeholder">Hai đội thua bán kết</div>'}html+='</div>'}html+='</div></div>'}$('content').innerHTML=html;}
function renderTeams(){$('content').innerHTML=`<div class="section-head"><div><h2>32 đội tuyển tham dự</h2><p class="sub">Chọn theo thứ hạng thế giới trong từng khu vực · bộ dữ liệu 13/10/2026</p></div><span class="badge">14 / 6 / 5 / 5 / 2</span></div><div class="region-grid">${Object.entries(names).map(([r,n])=>`<div class="panel region-card"><span class="badge">${r} · ${V.teams.filter(t=>t.region===r).length} SUẤT</span><h3 style="margin-top:12px">${n}</h3>${V.teams.filter(t=>t.region===r).map(t=>`<div class="team"><span class="flag">${t.flag}</span>${t.name}<small>#${t.rank}</small></div>`).join('')}</div>`).join('')}</div><p class="sub" style="margin-top:20px">Nguồn dữ liệu ban đầu: <a href="https://www.volleyballer.jp/senior_world_ranking_men/" target="_blank" rel="noopener">bảng tổng hợp FIVB của Volleyballer</a>, ngày 13/10/2026. Bộ đội cố định cho mùa giả lập; không tự cập nhật trực tiếp. Nga được giữ theo bộ BXH đã chọn, không mô phỏng điều kiện tham dự thực tế. Sức mạnh mô phỏng dựa trên điểm BXH, có yếu tố ngẫu nhiên; không phải dự đoán chính thức.</p>`;}
function renderRules(){const rules=[['01 / Phân bổ suất','32 đội: CEV 14, NORCECA 6, AVC 5, CSV 5, CAVB 2. Các đội có thứ hạng thế giới cao nhất trong từng khu vực được chọn theo bộ dữ liệu hiển thị ở mục đội tuyển.'],['02 / League phase','Vòng tròn một lượt: 31 vòng × 16 trận = 496 trận. Mỗi đội gặp 31 đối thủ đúng một lần. Tất cả trận BO5, thắng 3 set để thắng trận.'],['03 / Xếp hạng','Xét số trận thắng giảm dần, số trận thua tăng dần, hiệu số set, hiệu số điểm. Nếu còn bằng nhau: số trận thắng đối đầu giữa các đội cùng nhóm bằng chỉ số; cuối cùng dùng thứ tự bốc thăm cố định từ đầu mùa. Không dùng điểm 3–2–1–0.'],['04 / Điểm số','Set 1–4 đến 25, set 5 đến 15, luôn cách biệt ít nhất 2 điểm. Hiệu số set = set thắng − set thua. Hiệu số điểm = điểm ghi − điểm chịu; ghi 140, chịu 120 là +20.'],['05 / Vé vớt','Top 12 vào thẳng playoff. Hạng 13–20 đấu BO5 loại trực tiếp: 13 vs 20, 14 vs 19, 15 vs 18, 16 vs 17. Hạng 21–32 bị loại.'],['06 / Seed & bốc thăm','Seed 1: hạng 1–4; seed 2: 5–8; seed 3: 9–12; seed 4: bốn đội thắng vé vớt. Mỗi nhánh A–D có đủ bốn seed. Vòng 16 đội: S1 vs S4 và S2 vs S3.'],['07 / Nhánh đấu cố định','Hai đội thắng vòng 16 trong cùng nhánh gặp nhau ở tứ kết. Thắng nhánh A gặp B, C gặp D ở bán kết. Không bốc thăm lại. Hai đội thắng vào chung kết, hai đội thua tranh hạng ba.'],['08 / Cách chơi & lưu','Mô phỏng từng trận, từng vòng hoặc toàn bộ league. Có thể nhập điểm từng set thủ công. Kết quả vòng trước bị khóa khi đã tạo vòng tiếp theo để giữ đúng nhánh. Tiến độ tự lưu trên trình duyệt; dùng Xuất / Nhập tiến độ để chuyển thiết bị.']];$('content').innerHTML=`<div class="section-head"><h2>Luật giải đấu</h2><span class="badge">CUSTOM WORLD CUP</span></div><div class="rule-grid">${rules.map(([h,p])=>`<div class="panel rule"><h3>${h}</h3><p>${p}</p></div>`).join('')}</div>`;}
function editMatch(id){let m=findMatch(id);if(!m||isLocked(m))return;editId=id;$('editorTitle').textContent=`${V.get(m.a).name} vs ${V.get(m.b).name}`;$('setInputs').innerHTML=Array.from({length:5},(_,i)=>`<div class="set-row"><label for="a${i}">Set ${i+1}</label><input aria-label="${V.get(m.a).name} set ${i+1}" id="a${i}" type="number" min="0" max="999" value="${m.sets?.[i]?.[0]??''}"><span>:</span><input aria-label="${V.get(m.b).name} set ${i+1}" id="b${i}" type="number" min="0" max="999" value="${m.sets?.[i]?.[1]??''}"></div>`).join('');$('formError').textContent='';$('editor').showModal()}
$('scoreForm').onsubmit=e=>{e.preventDefault();let sets=[],blank=false;for(let i=0;i<5;i++){let a=$('a'+i).value,b=$('b'+i).value;if(a===''&&b===''){blank=true;continue}if(blank||a===''||b===''){$('formError').textContent='Điền đủ hai đội và không bỏ trống set ở giữa.';return}sets.push([Number(a),Number(b)])}if(!V.validate(sets)){$('formError').textContent='Điểm chưa hợp lệ: thắng 3 set; set 1–4 đến 25, set 5 đến 15, cách biệt 2 điểm.';return}findMatch(editId).sets=sets;V.advance(state);save();$('editor').close();render();toast('Đã lưu kết quả')};
function exportSave(){let url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='volleyworld-tien-do.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function validSave(s){if(s?.version!==1||!Array.isArray(s.rounds)||s.rounds.length!==31||!Array.isArray(s.tie)||new Set(s.tie).size!==32||!s.tie.every(V.get))return false;let pairs=new Set(),ids=new Set();const check=m=>{if(!m||typeof m.id!=='string'||ids.has(m.id)||!V.get(m.a)||!V.get(m.b)||m.a===m.b||m.sets!==null&&!V.validate(m.sets))return false;ids.add(m.id);return true};for(const r of s.rounds){if(!Array.isArray(r)||r.length!==16||new Set(r.flatMap(m=>[m.a,m.b])).size!==32)return false;for(const m of r){if(!check(m))return false;pairs.add([m.a,m.b].sort().join('-'))}}if(pairs.size!==496)return false;if(s.playin!==null&&(!V.leagueDone(s)||!Array.isArray(s.playin)||s.playin.length!==4||!s.playin.every(check)))return false;if(s.bracket!==null){if(!s.playin?.every(m=>m.sets)||!s.bracket.seeds)return false;for(const[k,n]of [['r16',8],['qf',4],['sf',2],['final',1],['bronze',1]]){let a=s.bracket[k];if(!Array.isArray(a)||(a.length!==0&&a.length!==n)||!a.every(check))return false}if(s.bracket.r16.length!==8)return false;const ranks=V.standings(s).map(x=>x.id),p=s.playin;for(let i=0;i<4;i++)if(p[i].a!==ranks[12+i]||p[i].b!==ranks[19-i])return false;let eligible=[...ranks.slice(0,12),...p.map(V.winner)],r16=s.bracket.r16;if(new Set(r16.flatMap(m=>[m.a,m.b])).size!==16||!r16.every(m=>eligible.includes(m.a)&&eligible.includes(m.b)))return false;for(let i=0;i<8;i+=2){let seed=r16.slice(i,i+2).flatMap(m=>[m.a,m.b]).map(id=>s.bracket.seeds[id]).sort().join('');if(seed!=='1234')return false}for(const[src,dest]of [['r16','qf'],['qf','sf'],['sf','final']]){let a=s.bracket[src],b=s.bracket[dest];if(b.length&&(!a.every(m=>m.sets)||!b.every((m,i)=>m.a===V.winner(a[2*i])&&m.b===V.winner(a[2*i+1]))))return false}if(s.bracket.bronze.length&&(!s.bracket.sf.every(m=>m.sets)||s.bracket.bronze[0].a!==V.loser(s.bracket.sf[0])||s.bracket.bronze[0].b!==V.loser(s.bracket.sf[1])))return false;}return true}
$('import').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{let s=JSON.parse(await f.text());if(!validSave(s))throw Error();if(!confirm('Thay tiến độ hiện tại bằng file đã chọn?'))return;state=s;round=Math.max(0,state.rounds.findIndex(r=>r.some(m=>!m.sets)));save();render();toast('Đã khôi phục tiến độ')}catch{toast('File tiến độ không hợp lệ.')}e.target.value=''};
function resetGame(){if(!confirm('Tạo giải mới sẽ xóa tiến độ hiện tại trên trình duyệt. Hãy xuất tiến độ nếu muốn giữ lại.'))return;state=V.fresh();tab='league';round=0;save();render();toast('Giải mới đã sẵn sàng!')}
save();render();
